<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_once __DIR__.'/read-model.php'; require_once __DIR__.'/vehicle-store.php'; require_once __DIR__.'/vehicle-media.php';
try { kalite_filo_admin_require_method('GET'); kalite_filo_admin_start_session(); kalite_filo_admin_require_authentication(); $id=(string)($_GET['id']??''); $download=($_GET['download']??'')==='1'; $media=null; foreach(kalite_filo_admin_vehicle_records() as $record){if(($record['draftMedia']['id']??'')===$id){$media=$record['draftMedia'];break;}} if(!is_array($media))kalite_filo_admin_json(['error'=>'not_found'],404); $path=kalite_filo_admin_vehicle_media_path($id,(string)$media['extension']); if(!is_file($path))kalite_filo_admin_json(['error'=>'not_found'],404); header('Content-Type: '.(string)$media['mime']); header('Content-Length: '.filesize($path)); if($download)header('Content-Disposition: attachment; filename="vehicle-image.'.(string)$media['extension'].'"'); readfile($path); exit; } catch(Throwable $e){error_log('Media file failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
